  // 按指定顺序排序并转换为数组
export  const sortGroups = (map, order) => {
    const groups = Array.from(map.values())
    return groups.sort((a, b) => {
      const indexA = order.indexOf(a.group) // 确保group字段存在
      const indexB = order.indexOf(b.group)
      
      // 如果都在排序列表中，按列表顺序排序
      if (indexA !== -1 && indexB !== -1) {
        return indexA - indexB
      }
      // 如果只有A在列表中，A排前面
      if (indexA !== -1) return -1
      // 如果只有B在列表中，B排前面
      if (indexB !== -1) return 1
      // 都不在列表中，按字母顺序排序
      return a.group.localeCompare(b.group)
    })
  }

  /**
 * 数据结构处理：将平铺的设备数组转换为智能分组结构
 * @param {Array} flatArray - 平铺的设备数组
 * @param {Array} leftKeywords - 左侧分组关键词数组
 * @param {Array} rightKeywords - 右侧分组关键词数组
 * @param {Array} leftOrder - 左侧分组排序顺序数组
 * @param {Array} rightOrder - 右侧分组排序顺序数组
 * @param {string} defaultSide - 默认分组侧 ('left' 或 'right')
 * @returns {Object} 包含leftGroups和rightGroups的对象
 */
export const groupDevicesByGroup = (
  flatArray = [],
  leftKeywords = ['右', '头部'],
  rightKeywords = ['左', '腰部'],
  leftOrder = ['头部', '右臂', '右手', '右腿', '同构右臂'],
  rightOrder = ['左臂', '左手', '腰部', '左腿', '同构左臂'],
  defaultSide = 'left'
) => {
    if (!Array.isArray(flatArray)) {
      console.warn('groupDevicesByGroup: 参数必须是数组')
      return { leftGroups: [], rightGroups: [] }
    }
    
    // 初始化分组Map
    const leftMap = new Map()
    const rightMap = new Map()
    
    flatArray.forEach(item => {
      if (!item || typeof item !== 'object') return
      
      const groupName = item.group || '未分组'
      const group = item.group || groupName
      
      // 判断分组归属
      let targetMap = null
      if (leftKeywords.some(keyword => group.includes(keyword))) {
        targetMap = leftMap
      } else if (rightKeywords.some(keyword => group.includes(keyword))) {
        targetMap = rightMap
      } else {
        // 根据默认侧分配
        targetMap = defaultSide === 'left' ? leftMap : rightMap
      }
      
      // 创建或获取分组
      if (!targetMap.has(group)) {
        targetMap.set(group, {
          group: group,
          items: []
        })
      }
      
      targetMap.get(group).items.push(item)
    })
    
    return {
      leftGroups: sortGroups(leftMap, leftOrder),
      rightGroups: sortGroups(rightMap, rightOrder)
    }
}

// 天工/工站 系列获取设备组配置
export const getDeviceGroups = (modelType, isUbtech = false) => {
  const config = DEVICE_GROUPS[modelType]
  if (!config) {
    console.warn(`未找到型号 ${modelType} 的配置，使用默认配置`)
    return DEVICE_GROUPS['tg-l']
  }
  
  return {
    title: isUbtech && config.ubtechTitle ? config.ubtechTitle : config.title,
    image: isUbtech && config.ubtechImage ? config.ubtechImage : config.image,
  }
}

