<template>
  <div>
    <div class="header flex-space-between">
      <!-- 天工Lite 2.0\天工Lite\天工Plus 2.0\天工Pro 2.0 型号共用 -->
       <!--2025.11.16 新增 工站lite\工站lite-H\工站Plus\工站Plus-H 共用 -->
       <!-- 2026.2.6  新增 天工2.0Pro/Plus雷达版 共用-->
      <div class="left" v-if="brandReady">{{ deviceConfig.title  }}</div>
      <!-- 工站的不展示电量 -->
      <div class="right" v-if="!versionStore.currentVersion.includes('gz-')">
        <span class="battery-text">{{ batteryText }}</span>
        <img :src="batteryIcon" alt="battery" class="battery-icon" />
      </div>
    </div>

    <!-- 状态图例 -->
    <div class="status-legend">
      <div
        class="legend-item"
        v-for="(status, key) in STATUS_CONFIG"
        :key="key"
      >
        <div
          class="status-indicator"
          :style="{ backgroundColor: status.color }"
        ></div>
        <span>{{ status.label }}</span>
      </div>
    </div>

    <div class="bottom flex-space-between">
      <!-- 左侧设备组 -->
      <DeviceGroup :groups="deviceGroups.leftGroups" />
      <!-- 中间图片 -->
      <div class="pic" v-if="brandReady">
        <img :src="deviceConfig.image" alt="" />
      </div>
      <!-- 右侧设备组 -->
      <DeviceGroup :groups="deviceGroups.rightGroups" />
    </div>
  </div>
</template>

<script setup>
import { computed, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { useWslStore } from '@/store/modules/ws.js'
import { useBrandStore } from '@/store/modules/brand'
import proto from '@/utils/sdkapi_pb.js'
import { getDeviceGroups,groupDevicesByGroup } from './const'
import { useVersionStore } from '@/store/modules/version'
import DeviceGroup from './deviceGroup.vue'

const store = useWslStore()
const { received, isConnected } = storeToRefs(store)

import { STATUS_CONFIG } from '@/constants/status'
import { useStatus } from '@/hooks/useStatus'
const { getStatusColor } = useStatus()

// 品牌配置
const brand = useBrandStore()
const brandReady = computed(() => brand.brandReady)
// 版本
const versionStore = useVersionStore()
console.log('index-tg: currentVersion',versionStore.currentVersion)
// 标题和图片配置
const deviceConfig = computed(() => 
  getDeviceGroups(versionStore.currentVersion, brand.isUbtech)
)

// 监听连接状态
watch(
  () => isConnected.value,
  (newStatus) => {
    if (newStatus) {
      // 当连接成功时发送命令13
      const request = new proto.Request()
      request.setCommand(proto.Command.CMD_GET_STATUS_DATA)
      const data = request.serializeBinary()
      store.websocketSendData({ data })
    }
  },
  { immediate: true } // 立即执行一次
)

// 合并多个数组（手臂、腰部 等数据不在同一个数组字段中，合并哪一个需要根据具体型号分析）
  const allDevices = computed(() =>{
    const statusData = received.value?.statusData || {}
    return [
      ...(statusData.motorDataList || []),
      ...(statusData.sixDofDataList || []),
      ...(statusData.handDataList || []),
      ...(statusData.gripperDataList || []),
    ]
  })
// 智能分组展示（左右）
const deviceGroups = computed(() => groupDevicesByGroup(allDevices.value))
console.log('智能分组结果', deviceGroups.value?.leftGroups, deviceGroups.value?.rightGroups)

const batteryPercentage = computed(() => {
  const batteryLevel =
    received.value?.statusData?.powerDataList?.[0]?.batteryLevel
  return batteryLevel !== undefined && batteryLevel !== null
    ? Number(batteryLevel)
    : null
})

const batteryIcon = computed(() => {
  if (batteryPercentage.value === null) {
    return require('@/assets/img/battery/battery-10.png')
  }
  
  if (batteryPercentage.value <= 20) {
    return require('@/assets/img/battery/battery-10.png')
  } else if (batteryPercentage.value <= 50) {
    return require('@/assets/img/battery/battery-30.png')
  } else if (batteryPercentage.value <= 90) {
    return require('@/assets/img/battery/battery-70.png')
  } else {
    return require('@/assets/img/battery/battery-100.png')
  }
})

const batteryText = computed(() => {
  if (batteryPercentage.value === null) {
    return '电量未知'
  }
  
  if (batteryPercentage.value <= 20) {
    return '电量低'
  } else if (batteryPercentage.value <= 50) {
    return '电量不足'
  } else if (batteryPercentage.value <= 90) {
    return '电量充足'
  } else {
    return '电量满'
  }
})
</script>

